mapper.select:
select concat(grouped.uav_id, '_', grouped.trace_id) as targetId, ( select latest.uav_model from data_tdoa_target latest where latest.uav_id = grouped.uav_id and latest.trace_id = grouped.trace_id and latest.timestamp >= #{startDateTime} and latest.timestamp < #{endDateTime}
and latest.target_type = #{targetType}
order by latest.timestamp desc, latest.id desc limit 1 ) as uavModel, grouped.timestampBegin, grouped.timestampEnd, timestampdiff(second, grouped.timestampBegin, grouped.timestampEnd) as duration, grouped.recordCount from ( select dtt.uav_id, dtt.trace_id, min(dtt.timestamp) as timestampBegin, max(dtt.timestamp) as timestampEnd, count(1) as recordCount from data_tdoa_target dtt where dtt.uav_id is not null and dtt.trace_id is not null and dtt.timestamp >= #{startDateTime} and dtt.timestamp < #{endDateTime}
and dtt.target_type = #{targetType}
group by dtt.uav_id, dtt.trace_id ) grouped order by grouped.timestampEnd desc
